import { Controller, Post, Body, Injectable, Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import * as ldap from 'ldapjs';

@Injectable()
class LdapService {
  private client: any;

  constructor() {
    this.client = ldap.createClient({
      url: process.env.LDAP_URL || 'ldap://ldap.internal.corp:389',
      timeout: 5000,
      connectTimeout: 10000,
    });
  }

  async authenticate(username: string, password: string): Promise<any> {
    const baseDN = process.env.LDAP_BASE_DN || 'dc=corp,dc=internal';

    // Build search filter to find user entry
    // Note: username is used to locate the DN before bind
    const searchFilter = `(&(objectClass=person)(uid=${username}))`;

    return new Promise((resolve, reject) => {
      this.client.search(baseDN, {
        filter: searchFilter,
        scope: 'sub',
        attributes: ['dn', 'cn', 'mail', 'memberOf'],
      }, (err: any, res: any) => {
        if (err) return reject(err);

        const entries: any[] = [];
        res.on('searchEntry', (entry: any) => entries.push(entry));
        res.on('error', (e: any) => reject(e));
        res.on('end', () => {
          if (entries.length === 0) {
            return reject(new Error('User not found'));
          }
          // Attempt bind with found DN
          const userDN = entries[0].objectName;
          this.client.bind(userDN, password, (bindErr: any) => {
            if (bindErr) return reject(new Error('Invalid credentials'));
            resolve({
              dn: userDN,
              cn: entries[0].attributes?.find((a: any) => a.type === 'cn')?.values[0],
              mail: entries[0].attributes?.find((a: any) => a.type === 'mail')?.values[0],
              groups: entries[0].attributes?.find((a: any) => a.type === 'memberOf')?.values || [],
            });
          });
        });
      });
    });
  }

  async searchUsers(query: string, department: string): Promise<any[]> {
    const baseDN = process.env.LDAP_BASE_DN || 'dc=corp,dc=internal';

    // Search for users matching query within department
    const filter = `(&(objectClass=inetOrgPerson)(department=${department})(|(cn=*${query}*)(mail=*${query}*)))`;

    return new Promise((resolve, reject) => {
      this.client.search(baseDN, {
        filter: filter,
        scope: 'sub',
        attributes: ['cn', 'mail', 'department', 'title'],
        sizeLimit: 100,
      }, (err: any, res: any) => {
        if (err) return reject(err);

        const results: any[] = [];
        res.on('searchEntry', (entry: any) => results.push(entry.object));
        res.on('error', (e: any) => reject(e));
        res.on('end', () => resolve(results));
      });
    });
  }
}

@Controller('api/v2/directory')
class DirectoryController {
  constructor(private readonly ldapService: LdapService) {}

  @Post('authenticate')
  async authenticate(@Body() body: { username: string; password: string }) {
    if (!body.username || !body.password) {
      return { error: 'Username and password required' };
    }
    try {
      const user = await this.ldapService.authenticate(body.username, body.password);
      return { success: true, user };
    } catch (e: any) {
      return { success: false, error: e.message };
    }
  }

  @Post('search')
  async search(@Body() body: { query: string; department: string }) {
    if (!body.query || !body.department) {
      return { error: 'Query and department required' };
    }
    try {
      const users = await this.ldapService.searchUsers(body.query, body.department);
      return { results: users };
    } catch (e: any) {
      return { error: 'Search failed', detail: e.message };
    }
  }
}

@Module({
  controllers: [DirectoryController],
  providers: [LdapService],
})
class AppModule {}

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000);
}
bootstrap();
